//! PROTOTYPE — throwaway. Wayfinder ticket #58.
//!
//! Three variants of the *visual language* for the new Overlays (Boss Spawns,
//! Sniper Zones, Minefields, Transits, Switches, BTR Stops), drawn on the real
//! map with real upstream data (`docs/prototypes/58-visual-language/overlays.json`,
//! generated by `gen.py` from json.tarkov.dev). Switch variants with the yellow
//! bar at the bottom of the map or ← / →. The sidebar gains a "PROTOTYPE" block
//! with the six new toggles (all Mobs on when Boss Spawns is on) so the sidebar
//! glyph of each variant can be judged next to the marker it teaches.
//!
//! Auto-screenshot: `TARKOV_MAP_PROTO_SHOTS=<dir>` walks every variant × scene
//! (see [`SCENES`]) and writes `<dir>/<variant>-<scene>.png`, then quits.

use crate::TarkovMapApp;
use crate::colors;
use crate::coordinates::game_to_display;
use eframe::egui::{self, Color32, Pos2, Rect, Stroke, Vec2};
use serde::Deserialize;
use std::collections::HashMap;
use tarkov_map::Map;

pub const VARIANTS: [&str; 3] = ["Solid shapes", "Hue families + chips", "Icons on dark discs"];

/// Screen-size threshold below which a Minefield outline is replaced by the
/// fixed-size fallback marker (max bbox side, in points).
pub const MINEFIELD_MIN_PX: f32 = 7.0;
/// Side of the fallback minefield marker, in points.
pub const MINEFIELD_MARKER_PX: f32 = 5.0;
/// Switches within this many game units share one marker (#31).
pub const SWITCH_CLUSTER_UNITS: f64 = 3.0;
/// Arrow glyph for the Transit label; egui's default fonts lack U+2192 "→".
pub const TRANSIT_ARROW: &str = "➡";
/// Candidate arrow glyphs shown in the bar so the missing ones can be spotted.
const ARROW_CANDIDATES: &str = "→ ➜ ➡ ⇒ » ▶ ▸ ⮕ ⟶";

// ---------------------------------------------------------------- data ----

#[derive(Deserialize, Default)]
pub struct MapOverlays {
    pub boss_spawns: Vec<BossSpawn>,
    pub sniper_zones: Vec<Vec<[f64; 2]>>,
    pub minefields: Vec<Vec<[f64; 2]>>,
    pub transits: Vec<Transit>,
    pub switches: Vec<Switch>,
    pub btr_stops: Vec<BtrStop>,
}

#[derive(Deserialize)]
pub struct BossSpawn {
    pub position: [f64; 2],
    pub mobs: Vec<Mob>,
}

#[derive(Deserialize)]
pub struct Mob {
    pub name: String,
    pub chance: f64,
}

#[derive(Deserialize)]
pub struct Transit {
    pub position: [f64; 2],
    pub target: String,
}

#[derive(Deserialize)]
pub struct Switch {
    pub position: [f64; 2],
    pub name: String,
}

#[derive(Deserialize)]
pub struct BtrStop {
    pub position: [f64; 2],
    pub name: String,
}

const DATA: &str = include_str!("../../../docs/prototypes/58-visual-language/overlays.json");

// --------------------------------------------------------------- state ----

#[derive(Clone, Copy)]
pub struct ProtoToggles {
    pub bosses: bool,
    pub sniper_zones: bool,
    pub minefields: bool,
    pub transits: bool,
    pub switches: bool,
    pub btr_stops: bool,
}

impl Default for ProtoToggles {
    fn default() -> Self {
        Self {
            bosses: true,
            sniper_zones: true,
            minefields: true,
            transits: true,
            switches: true,
            btr_stops: true,
        }
    }
}

pub struct ProtoState {
    pub variant: usize,
    /// Skip a boss/switch label that would overlap one already drawn (K toggles).
    pub cull_labels: bool,
    pub toggles: ProtoToggles,
    pub data: HashMap<String, MapOverlays>,
    /// One-shot: centre the view on this game position at the current zoom.
    pub focus: Option<[f64; 2]>,
    shots: Option<Shots>,
}

struct Shots {
    dir: std::path::PathBuf,
    next: usize,
    settle: u32,
    pending: bool,
}

struct Scene {
    name: &'static str,
    map: &'static str,
    zoom: f32,
    focus: Option<[f64; 2]>,
    cull: bool,
}

const SCENES: &[Scene] = &[
    Scene { name: "lighthouse-fit", map: "lighthouse", zoom: 1.0, focus: None, cull: true },
    Scene { name: "lighthouse-fit-nocull", map: "lighthouse", zoom: 1.0, focus: None, cull: false },
    Scene { name: "lighthouse-zoom3", map: "lighthouse", zoom: 3.0, focus: Some([-160.0, -220.0]), cull: true },
    Scene { name: "ground-zero-fit", map: "ground-zero", zoom: 1.0, focus: None, cull: true },
    Scene { name: "ground-zero-fit-nocull", map: "ground-zero", zoom: 1.0, focus: None, cull: false },
    Scene { name: "ground-zero-zoom3", map: "ground-zero", zoom: 3.0, focus: Some([120.0, -60.0]), cull: true },
    Scene { name: "the-lab-fit", map: "the-lab", zoom: 1.0, focus: None, cull: true },
    Scene { name: "the-lab-zoom2", map: "the-lab", zoom: 2.0, focus: Some([-200.0, -340.0]), cull: true },
    Scene { name: "woods-fit", map: "woods", zoom: 1.0, focus: None, cull: true },
    Scene { name: "streets-zoom2", map: "streets-of-tarkov", zoom: 2.0, focus: Some([70.0, 310.0]), cull: true },
    Scene { name: "interchange-fit", map: "interchange", zoom: 1.0, focus: None, cull: true },
];

impl ProtoState {
    pub fn from_env() -> Self {
        let data: HashMap<String, MapOverlays> =
            serde_json::from_str(DATA).expect("prototype overlays.json");
        let shots = std::env::var_os("TARKOV_MAP_PROTO_SHOTS").map(|dir| Shots {
            dir: dir.into(),
            next: 0,
            settle: 0,
            pending: false,
        });
        Self {
            variant: 0,
            cull_labels: true,
            toggles: ProtoToggles::default(),
            data,
            focus: None,
            shots,
        }
    }
}

// --------------------------------------------------------- palette ----

/// Per-variant colours. Existing palette for reference: spawns green circle,
/// PMC extract royal blue square, scav orange, shared purple, player red.
struct Palette {
    boss_fill: Color32,
    boss_stroke: Color32,
    sniper_fill: Color32,
    sniper_stroke: Color32,
    mine_fill: Color32,
    mine_stroke: Color32,
    transit_fill: Color32,
    transit_stroke: Color32,
    switch_fill: Color32,
    switch_stroke: Color32,
    btr_fill: Color32,
    btr_stroke: Color32,
}

fn rgba(r: u8, g: u8, b: u8, a: u8) -> Color32 {
    Color32::from_rgba_unmultiplied(r, g, b, a)
}

fn palette(variant: usize) -> Palette {
    match variant {
        // A — solid shapes: distinct hues, opaque, dark strokes.
        0 => Palette {
            boss_fill: Color32::from_rgb(20, 20, 20),
            boss_stroke: Color32::from_rgb(240, 240, 240),
            sniper_fill: rgba(220, 40, 40, 55),
            sniper_stroke: rgba(220, 40, 40, 200),
            mine_fill: rgba(255, 110, 0, 110),
            mine_stroke: rgba(180, 60, 0, 220),
            transit_fill: Color32::from_rgb(0, 190, 190),
            transit_stroke: Color32::from_rgb(0, 90, 90),
            switch_fill: Color32::from_rgb(250, 215, 40),
            switch_stroke: Color32::from_rgb(120, 90, 0),
            btr_fill: Color32::from_rgb(218, 165, 32),
            btr_stroke: Color32::from_rgb(90, 60, 0),
        },
        // B — hue families: danger = crimson/magenta, navigation = cyan.
        1 => Palette {
            boss_fill: Color32::from_rgb(190, 30, 80),
            boss_stroke: Color32::from_rgb(255, 230, 240),
            sniper_fill: rgba(230, 60, 160, 35),
            sniper_stroke: rgba(230, 60, 160, 230),
            mine_fill: rgba(230, 40, 60, 90),
            mine_stroke: rgba(255, 90, 110, 240),
            transit_fill: Color32::from_rgb(40, 200, 220),
            transit_stroke: Color32::from_rgb(10, 70, 90),
            switch_fill: Color32::from_rgb(120, 220, 230),
            switch_stroke: Color32::from_rgb(10, 70, 90),
            btr_fill: Color32::from_rgb(20, 160, 200),
            btr_stroke: Color32::from_rgb(10, 70, 90),
        },
        // C — icons on dark discs: coloured icon on near-black disc.
        _ => Palette {
            boss_fill: rgba(25, 25, 25, 235),
            boss_stroke: Color32::from_rgb(245, 245, 245),
            sniper_fill: rgba(255, 60, 60, 20),
            sniper_stroke: rgba(255, 70, 70, 240),
            mine_fill: rgba(255, 140, 0, 30),
            mine_stroke: rgba(255, 150, 20, 240),
            transit_fill: rgba(25, 25, 25, 235),
            transit_stroke: Color32::from_rgb(80, 220, 230),
            switch_fill: rgba(25, 25, 25, 235),
            switch_stroke: Color32::from_rgb(255, 225, 60),
            btr_fill: rgba(25, 25, 25, 235),
            btr_stroke: Color32::from_rgb(240, 180, 40),
        },
    }
}

// -------------------------------------------------------- app hooks ----

impl TarkovMapApp {
    pub fn proto_shots_active(&self) -> bool {
        self.prototype.shots.is_some()
    }

    fn proto_map_data(&self, map: &Map) -> Option<&MapOverlays> {
        self.prototype.data.get(&map.normalized_name)
    }

    /// PROTOTYPE sidebar block: the six new toggles with the variant's glyph.
    pub fn show_prototype_sidebar(&mut self, ui: &mut egui::Ui) {
        Self::section_header(ui, "Prototype overlays");
        let v = self.prototype.variant;
        let pal = palette(v);
        let mut t = self.prototype.toggles;
        proto_toggle(ui, &mut t.bosses, "Bosses (all Mobs)", v, Kind::Boss, &pal);
        proto_toggle(ui, &mut t.sniper_zones, "Sniper zones", v, Kind::Sniper, &pal);
        proto_toggle(ui, &mut t.minefields, "Minefields", v, Kind::Mine, &pal);
        proto_toggle(ui, &mut t.transits, "Transits", v, Kind::Transit, &pal);
        proto_toggle(ui, &mut t.btr_stops, "BTR stops", v, Kind::Btr, &pal);
        proto_toggle(ui, &mut t.switches, "Switches", v, Kind::Switch, &pal);
        self.prototype.toggles = t;
    }

    /// One-shot focus for the screenshot driver: pan so `focus` is centred.
    pub fn proto_apply_focus(&mut self, map: &Map, viewport_rect: Rect, fit_scale: f32) {
        let Some(focus) = self.prototype.focus.take() else {
            return;
        };
        let logical_size = egui::vec2(map.logical_size[0], map.logical_size[1]);
        let display_size = logical_size * fit_scale * self.zoom;
        let map_rect = Rect::from_center_size(viewport_rect.center(), display_size);
        if let Some(p) = game_to_display(map, map_rect, focus) {
            self.pan_offset = viewport_rect.center() - p;
        }
    }

    /// Area Overlays — drawn right after the map image, beneath every marker.
    pub fn proto_draw_areas(&self, ui: &mut egui::Ui, map_rect: Rect, map: &Map, zoom: f32) {
        let Some(data) = self.proto_map_data(map) else {
            return;
        };
        let v = self.prototype.variant;
        let pal = palette(v);
        let t = self.prototype.toggles;
        let painter = ui.painter();
        let to_screen = |p: &[f64; 2]| game_to_display(map, map_rect, *p);

        if t.sniper_zones {
            for outline in &data.sniper_zones {
                let pts: Vec<Pos2> = outline.iter().filter_map(to_screen).collect();
                if pts.len() < 3 {
                    continue;
                }
                draw_area(painter, &pts, pal.sniper_fill, pal.sniper_stroke, v, false, zoom);
            }
        }
        if t.minefields {
            for outline in &data.minefields {
                let pts: Vec<Pos2> = outline.iter().filter_map(to_screen).collect();
                if pts.len() < 3 {
                    continue;
                }
                let bbox = Rect::from_points(&pts);
                if !map_rect.expand(50.0).intersects(bbox) {
                    continue;
                }
                if bbox.width().max(bbox.height()) < MINEFIELD_MIN_PX {
                    draw_minefield_marker(painter, bbox.center(), v, &pal);
                } else {
                    draw_area(painter, &pts, pal.mine_fill, pal.mine_stroke, v, true, zoom);
                }
            }
        }
    }

    /// Marker Overlays — drawn after spawns/extracts, before the player marker.
    pub fn proto_draw_markers(&self, ui: &mut egui::Ui, map_rect: Rect, map: &Map, zoom: f32) {
        let Some(data) = self.proto_map_data(map) else {
            return;
        };
        let v = self.prototype.variant;
        let pal = palette(v);
        let t = self.prototype.toggles;
        let painter = ui.painter();
        let visible = map_rect.expand(40.0);
        let to_screen = |p: &[f64; 2]| game_to_display(map, map_rect, *p);
        // Boss/switch labels claim screen space greedily; `cull_labels` off = #29 as decided.
        let mut placed: Vec<Rect> = Vec::new();
        let cull = self.prototype.cull_labels;

        // Transits: extract-style marker + "→ Map" label.
        if t.transits {
            for tr in &data.transits {
                let Some(pos) = to_screen(&tr.position) else { continue };
                if !visible.contains(pos) {
                    continue;
                }
                let size = marker_size(zoom);
                let label = format!("{} {}", TRANSIT_ARROW, tr.target);
                match v {
                    0 => {
                        let rect = Rect::from_center_size(pos, Vec2::splat(size));
                        painter.rect_filled(rect, 2.0, pal.transit_fill);
                        painter.rect_stroke(rect, 2.0, Stroke::new(2.0, pal.transit_stroke), egui::StrokeKind::Outside);
                        label_outlined(painter, pos, size, &label, zoom, Color32::WHITE, None);
                    }
                    1 => {
                        // Chevron pointing right, filled.
                        let h = size * 0.5;
                        let pts = vec![
                            pos + egui::vec2(-h, -h),
                            pos + egui::vec2(0.0, -h),
                            pos + egui::vec2(h, 0.0),
                            pos + egui::vec2(0.0, h),
                            pos + egui::vec2(-h, h),
                            pos + egui::vec2(-h * 0.3, 0.0),
                        ];
                        painter.add(egui::Shape::closed_line(pts.clone(), Stroke::new(2.0, pal.transit_stroke)));
                        painter.add(egui::Shape::convex_polygon(pts, pal.transit_fill, Stroke::NONE));
                        label_chip(painter, pos, size, &label, zoom, pal.transit_fill, None);
                    }
                    _ => {
                        disc(painter, pos, size, pal.transit_fill, pal.transit_stroke);
                        icon_chevrons(painter, pos, size, pal.transit_stroke);
                        label_outlined(painter, pos, size, &label, zoom, pal.transit_stroke, None);
                    }
                }
            }
        }

        // BTR stops: octagon / stop-sign + name label.
        if t.btr_stops {
            for stop in &data.btr_stops {
                let Some(pos) = to_screen(&stop.position) else { continue };
                if !visible.contains(pos) {
                    continue;
                }
                let size = marker_size(zoom);
                match v {
                    0 => {
                        octagon(painter, pos, size * 0.55, pal.btr_fill, Stroke::new(1.5, pal.btr_stroke));
                        label_outlined(painter, pos, size, &stop.name, zoom, Color32::WHITE, None);
                    }
                    1 => {
                        octagon(painter, pos, size * 0.55, pal.btr_fill, Stroke::new(1.5, pal.btr_stroke));
                        // white inner bar like a stop sign
                        let bar = Rect::from_center_size(pos, egui::vec2(size * 0.55, size * 0.16));
                        painter.rect_filled(bar, 1.0, Color32::WHITE);
                        label_chip(painter, pos, size, &stop.name, zoom, pal.btr_fill, None);
                    }
                    _ => {
                        disc(painter, pos, size, pal.btr_fill, pal.btr_stroke);
                        octagon(painter, pos, size * 0.32, pal.btr_stroke, Stroke::NONE);
                        label_outlined(painter, pos, size, &stop.name, zoom, pal.btr_stroke, None);
                    }
                }
            }
        }

        // Switches: clustered within 3 game units, stacked names.
        if t.switches {
            for (gp, names) in cluster_switches(&data.switches) {
                let Some(pos) = to_screen(&gp) else { continue };
                if !visible.contains(pos) {
                    continue;
                }
                let size = marker_size(zoom) * 0.8;
                let label = names.join("\n");
                match v {
                    0 => {
                        painter.circle(pos, size * 0.4, pal.switch_fill, Stroke::new(1.5, pal.switch_stroke));
                        label_outlined(painter, pos, size, &label, zoom, Color32::WHITE, cull.then_some(&mut placed));
                    }
                    1 => {
                        diamond(painter, pos, size * 0.5, pal.switch_fill, Stroke::new(1.5, pal.switch_stroke));
                        label_chip(painter, pos, size, &label, zoom, pal.switch_fill, cull.then_some(&mut placed));
                    }
                    _ => {
                        disc(painter, pos, size, pal.switch_fill, pal.switch_stroke);
                        icon_bolt(painter, pos, size, pal.switch_stroke);
                        label_outlined(painter, pos, size, &label, zoom, pal.switch_stroke, cull.then_some(&mut placed));
                    }
                }
            }
        }

        // Boss Spawns: one marker per position, stacked "Name NN%" lines.
        if t.bosses {
            for bs in &data.boss_spawns {
                let Some(pos) = to_screen(&bs.position) else { continue };
                if !visible.contains(pos) {
                    continue;
                }
                let size = marker_size(zoom) * 0.9;
                let label = bs
                    .mobs
                    .iter()
                    .map(|m| {
                        if m.chance >= 0.995 {
                            m.name.clone()
                        } else {
                            format!("{} {}%", m.name, (m.chance * 100.0).round() as i64)
                        }
                    })
                    .collect::<Vec<_>>()
                    .join("\n");
                match v {
                    0 => {
                        diamond(painter, pos, size * 0.55, pal.boss_fill, Stroke::new(1.5, pal.boss_stroke));
                        label_outlined(painter, pos, size, &label, zoom, Color32::WHITE, cull.then_some(&mut placed));
                    }
                    1 => {
                        // crimson dot with two "eyes" — a skull cue without an icon font
                        painter.circle(pos, size * 0.45, pal.boss_fill, Stroke::new(1.5, pal.boss_stroke));
                        let e = size * 0.14;
                        painter.circle_filled(pos + egui::vec2(-e, -e * 0.3), e * 0.55, pal.boss_stroke);
                        painter.circle_filled(pos + egui::vec2(e, -e * 0.3), e * 0.55, pal.boss_stroke);
                        label_chip(painter, pos, size, &label, zoom, pal.boss_fill, cull.then_some(&mut placed));
                    }
                    _ => {
                        disc(painter, pos, size, pal.boss_fill, pal.boss_stroke);
                        icon_skull(painter, pos, size, pal.boss_stroke, pal.boss_fill);
                        label_outlined(painter, pos, size, &label, zoom, Color32::WHITE, cull.then_some(&mut placed));
                    }
                }
            }
        }
    }

    /// Floating switcher bar + keyboard cycling + screenshot driver.
    pub fn show_prototype_bar(&mut self, ctx: &egui::Context, panel_rect: Rect) {
        let n = VARIANTS.len();
        if !ctx.egui_wants_keyboard_input() {
            ctx.input(|i| {
                if i.key_pressed(egui::Key::ArrowRight) {
                    self.prototype.variant = (self.prototype.variant + 1) % n;
                }
                if i.key_pressed(egui::Key::ArrowLeft) {
                    self.prototype.variant = (self.prototype.variant + n - 1) % n;
                }
                if i.key_pressed(egui::Key::K) {
                    self.prototype.cull_labels = !self.prototype.cull_labels;
                }
            });
        }

        let bar_w = 520.0;
        let pos = egui::pos2(panel_rect.center().x - bar_w / 2.0, panel_rect.bottom() - 60.0);
        egui::Area::new(egui::Id::new("prototype_bar"))
            .fixed_pos(pos)
            .order(egui::Order::Foreground)
            .show(ctx, |ui| {
                egui::Frame::popup(ui.style())
                    .fill(Color32::from_rgb(250, 230, 90))
                    .stroke(Stroke::new(1.5, Color32::BLACK))
                    .corner_radius(18)
                    .show(ui, |ui| {
                        ui.set_width(bar_w);
                        ui.visuals_mut().override_text_color = Some(Color32::BLACK);
                        ui.horizontal(|ui| {
                            if ui.button("◀").clicked() {
                                self.prototype.variant = (self.prototype.variant + n - 1) % n;
                            }
                            let key = (b'A' + self.prototype.variant as u8) as char;
                            ui.label(
                                egui::RichText::new(format!(
                                    "PROTOTYPE  {key} — {}",
                                    VARIANTS[self.prototype.variant]
                                ))
                                .strong(),
                            );
                            if ui.button("▶").clicked() {
                                self.prototype.variant = (self.prototype.variant + 1) % n;
                            }
                            ui.checkbox(&mut self.prototype.cull_labels, "cull");
                            ui.label(ARROW_CANDIDATES);
                        });
                    });
            });

        self.drive_screenshots(ctx);
    }

    fn drive_screenshots(&mut self, ctx: &egui::Context) {
        if self.prototype.shots.is_none() {
            return;
        }
        let total = VARIANTS.len() * SCENES.len();
        let uploaded = self
            .selected_map()
            .map(|m| {
                matches!(
                    self.asset_cache.state(&m.image_path),
                    Some(crate::assets::AssetLoadState::Uploaded)
                )
            })
            .unwrap_or(false);

        let mut delivered = None;
        ctx.input(|i| {
            for ev in &i.raw.events {
                if let egui::Event::Screenshot { image, .. } = ev {
                    delivered = Some(image.clone());
                }
            }
        });
        if let Some(image) = delivered {
            let shots = self.prototype.shots.as_mut().unwrap();
            let (v, s) = (shots.next / SCENES.len(), shots.next % SCENES.len());
            let key = (b'A' + v as u8) as char;
            let path = shots.dir.join(format!("{key}-{}.png", SCENES[s].name));
            std::fs::create_dir_all(&shots.dir).ok();
            let [w, h] = image.size;
            let rgba: Vec<u8> = image.pixels.iter().flat_map(|c| c.to_srgba_unmultiplied()).collect();
            image::save_buffer(&path, &rgba, w as u32, h as u32, image::ColorType::Rgba8)
                .expect("write screenshot");
            eprintln!("saved {}", path.display());
            shots.next += 1;
            shots.pending = false;
            shots.settle = 0;
            if shots.next >= total {
                ctx.send_viewport_cmd(egui::ViewportCommand::Close);
                return;
            }
        }

        let (next, pending) = {
            let shots = self.prototype.shots.as_ref().unwrap();
            (shots.next, shots.pending)
        };
        if pending || next >= total {
            ctx.request_repaint();
            return;
        }

        let (v, s) = (next / SCENES.len(), next % SCENES.len());
        let scene = &SCENES[s];
        let settle = {
            let shots = self.prototype.shots.as_mut().unwrap();
            shots.settle += 1;
            shots.settle
        };
        if settle == 1 {
            // Window size is left to the WM; docs/prototypes/58-visual-language/shoot.sh floats it at 1100×900.
            self.prototype.variant = v;
            self.prototype.toggles = ProtoToggles::default();
            self.prototype.cull_labels = scene.cull;
            self.overlays.labels = false;
            if let Some(idx) = self.maps.iter().position(|m| m.normalized_name == scene.map) {
                self.selected_map = idx;
            }
            self.zoom = scene.zoom;
            self.prev_zoom = scene.zoom;
            self.pan_offset = Vec2::ZERO;
            self.prototype.focus = scene.focus;
        }
        // Wait until the map texture is up, then let the crossfade finish.
        let shots = self.prototype.shots.as_mut().unwrap();
        if !uploaded {
            shots.settle = shots.settle.min(2);
        }
        // The first shot waits longer so an external window float/resize can land.
        let needed = if shots.next == 0 { 300 } else { 60 };
        if shots.settle > needed {
            shots.pending = true;
            ctx.send_viewport_cmd(egui::ViewportCommand::Screenshot(Default::default()));
        }
        ctx.request_repaint();
    }
}

// ------------------------------------------------------- primitives ----

fn marker_size(zoom: f32) -> f32 {
    (12.0 * zoom).clamp(8.0, 32.0)
}

fn label_font(zoom: f32) -> egui::FontId {
    egui::FontId::proportional((6.0 * zoom).clamp(9.0, 18.0))
}

/// Greedy label placement: a label whose box overlaps one already placed
/// this frame is skipped (the marker still draws). `None` = never cull.
type Placed<'a> = Option<&'a mut Vec<Rect>>;

fn claim(placed: Placed, rect: Rect) -> bool {
    match placed {
        None => true,
        Some(v) => {
            if v.iter().any(|r| r.intersects(rect)) {
                false
            } else {
                v.push(rect);
                true
            }
        }
    }
}

/// Outlined text above the marker (today's extract style), multi-line aware.
fn label_outlined(painter: &egui::Painter, pos: Pos2, size: f32, text: &str, zoom: f32, color: Color32, placed: Placed) {
    let font = label_font(zoom);
    let anchor = pos + egui::vec2(0.0, -size / 2.0 - 4.0);
    let galley = painter.layout_no_wrap(text.to_owned(), font.clone(), color);
    let top_left = anchor - egui::vec2(galley.size().x / 2.0, galley.size().y);
    if !claim(placed, Rect::from_min_size(top_left, galley.size())) {
        return;
    }
    for off in [egui::vec2(-1.0, 0.0), egui::vec2(1.0, 0.0), egui::vec2(0.0, -1.0), egui::vec2(0.0, 1.0)] {
        let g = painter.layout_no_wrap(text.to_owned(), font.clone(), colors::EXTRACT_TEXT_SHADOW);
        painter.galley(top_left + off, g, colors::EXTRACT_TEXT_SHADOW);
    }
    painter.galley(top_left, galley, color);
}

/// Text on a dark pill chip with a coloured left edge, above the marker.
fn label_chip(painter: &egui::Painter, pos: Pos2, size: f32, text: &str, zoom: f32, accent: Color32, placed: Placed) {
    let font = label_font(zoom);
    let galley = painter.layout_no_wrap(text.to_owned(), font, Color32::WHITE);
    let pad = egui::vec2(5.0, 2.0);
    let chip_size = galley.size() + pad * 2.0;
    let chip = Rect::from_min_size(
        pos + egui::vec2(-chip_size.x / 2.0, -size / 2.0 - 4.0 - chip_size.y),
        chip_size,
    );
    if !claim(placed, chip) {
        return;
    }
    painter.rect_filled(chip, 4.0, rgba(15, 15, 15, 190));
    painter.rect_filled(
        Rect::from_min_size(chip.min, egui::vec2(3.0, chip.height())),
        egui::CornerRadius { nw: 4, sw: 4, ne: 0, se: 0 },
        accent,
    );
    painter.galley(chip.min + pad + egui::vec2(1.5, 0.0), galley, Color32::WHITE);
}

fn disc(painter: &egui::Painter, pos: Pos2, size: f32, fill: Color32, ring: Color32) {
    painter.circle(pos, size * 0.5, fill, Stroke::new(1.5, ring));
}

fn regular_polygon(pos: Pos2, r: f32, n: usize, rot: f32) -> Vec<Pos2> {
    (0..n)
        .map(|i| {
            let a = rot + i as f32 * std::f32::consts::TAU / n as f32;
            pos + egui::vec2(a.cos() * r, a.sin() * r)
        })
        .collect()
}

fn octagon(painter: &egui::Painter, pos: Pos2, r: f32, fill: Color32, stroke: Stroke) {
    let pts = regular_polygon(pos, r, 8, std::f32::consts::PI / 8.0);
    painter.add(egui::Shape::convex_polygon(pts, fill, stroke));
}

fn diamond(painter: &egui::Painter, pos: Pos2, r: f32, fill: Color32, stroke: Stroke) {
    let pts = regular_polygon(pos, r, 4, 0.0);
    painter.add(egui::Shape::convex_polygon(pts, fill, stroke));
}

fn icon_skull(painter: &egui::Painter, pos: Pos2, size: f32, bone: Color32, dark: Color32) {
    let r = size * 0.24;
    let head = pos + egui::vec2(0.0, -r * 0.25);
    painter.circle_filled(head, r, bone);
    let jaw = Rect::from_center_size(head + egui::vec2(0.0, r * 0.95), egui::vec2(r * 1.1, r * 0.7));
    painter.rect_filled(jaw, 1.0, bone);
    let e = r * 0.42;
    painter.circle_filled(head + egui::vec2(-e, -r * 0.05), e * 0.6, dark);
    painter.circle_filled(head + egui::vec2(e, -r * 0.05), e * 0.6, dark);
}

fn icon_bolt(painter: &egui::Painter, pos: Pos2, size: f32, color: Color32) {
    let s = size * 0.28;
    let pts = vec![
        pos + egui::vec2(s * 0.35, -s),
        pos + egui::vec2(-s * 0.35, s * 0.1),
        pos + egui::vec2(s * 0.15, s * 0.1),
        pos + egui::vec2(-s * 0.35, s),
    ];
    painter.add(egui::Shape::line(pts, Stroke::new(size * 0.09, color)));
}

fn icon_chevrons(painter: &egui::Painter, pos: Pos2, size: f32, color: Color32) {
    let s = size * 0.22;
    let w = size * 0.09;
    for dx in [-s * 0.55, s * 0.35] {
        let pts = vec![
            pos + egui::vec2(dx - s * 0.4, -s),
            pos + egui::vec2(dx + s * 0.4, 0.0),
            pos + egui::vec2(dx - s * 0.4, s),
        ];
        painter.add(egui::Shape::line(pts, Stroke::new(w, color)));
    }
}

fn draw_area(painter: &egui::Painter, pts: &[Pos2], fill: Color32, stroke: Color32, variant: usize, is_mine: bool, zoom: f32) {
    let w = (1.0 + zoom * 0.2).min(2.0);
    match variant {
        // A: filled + solid stroke
        0 => {
            painter.add(egui::Shape::convex_polygon(pts.to_vec(), fill, Stroke::new(w, stroke)));
        }
        // B: filled + stroke; sniper zones dashed to read as "line of fire", mines solid
        1 => {
            painter.add(egui::Shape::convex_polygon(pts.to_vec(), fill, Stroke::NONE));
            let mut closed = pts.to_vec();
            closed.push(pts[0]);
            if is_mine {
                painter.add(egui::Shape::line(closed, Stroke::new(w, stroke)));
            } else {
                painter.add(egui::Shape::dashed_line(&closed, Stroke::new(w, stroke), 6.0, 4.0));
            }
        }
        // C: outline-first, faint fill; minefields dashed (a "do not cross" edge)
        _ => {
            painter.add(egui::Shape::convex_polygon(pts.to_vec(), fill, Stroke::NONE));
            let mut closed = pts.to_vec();
            closed.push(pts[0]);
            if is_mine {
                painter.add(egui::Shape::dashed_line(&closed, Stroke::new(w * 1.2, stroke), 4.0, 3.0));
            } else {
                painter.add(egui::Shape::line(closed, Stroke::new(w * 1.5, stroke)));
            }
        }
    }
}

fn draw_minefield_marker(painter: &egui::Painter, pos: Pos2, variant: usize, pal: &Palette) {
    let s = MINEFIELD_MARKER_PX;
    match variant {
        0 => {
            let rect = Rect::from_center_size(pos, Vec2::splat(s));
            painter.rect_filled(rect, 0.0, pal.mine_stroke);
        }
        1 => {
            painter.circle_filled(pos, s * 0.5, pal.mine_stroke);
        }
        _ => {
            // filled square (an "x" was tried first and is illegible at 5 px)
            let rect = Rect::from_center_size(pos, Vec2::splat(s));
            painter.rect_filled(rect, 1.0, pal.mine_stroke);
        }
    }
}

/// Switches within `SWITCH_CLUSTER_UNITS` share one marker; names stacked.
fn cluster_switches(switches: &[Switch]) -> Vec<([f64; 2], Vec<String>)> {
    let mut clusters: Vec<([f64; 2], Vec<String>)> = Vec::new();
    for s in switches {
        if let Some((c, names)) = clusters.iter_mut().find(|(c, _)| {
            let dx = c[0] - s.position[0];
            let dz = c[1] - s.position[1];
            (dx * dx + dz * dz).sqrt() <= SWITCH_CLUSTER_UNITS
        }) {
            names.push(s.name.clone());
            let _ = c;
        } else {
            clusters.push((s.position, vec![s.name.clone()]));
        }
    }
    clusters
}

// --------------------------------------------------- sidebar glyphs ----

#[derive(Clone, Copy)]
enum Kind {
    Boss,
    Sniper,
    Mine,
    Transit,
    Switch,
    Btr,
}

fn proto_toggle(ui: &mut egui::Ui, value: &mut bool, label: &str, variant: usize, kind: Kind, pal: &Palette) {
    ui.horizontal(|ui| {
        ui.checkbox(value, "");
        let (rect, _) = ui.allocate_exact_size(Vec2::splat(14.0), egui::Sense::hover());
        let p = ui.painter();
        let c = rect.center();
        let size = 13.0;
        match (kind, variant) {
            (Kind::Boss, 0) => diamond(p, c, 6.0, pal.boss_fill, Stroke::new(1.0, pal.boss_stroke)),
            (Kind::Boss, 1) => {
                p.circle(c, 5.5, pal.boss_fill, Stroke::new(1.0, pal.boss_stroke));
                p.circle_filled(c + egui::vec2(-1.8, -0.5), 1.0, pal.boss_stroke);
                p.circle_filled(c + egui::vec2(1.8, -0.5), 1.0, pal.boss_stroke);
            }
            (Kind::Boss, _) => {
                disc(p, c, size, pal.boss_fill, pal.boss_stroke);
                icon_skull(p, c, size, pal.boss_stroke, pal.boss_fill);
            }
            (Kind::Sniper, _) => {
                p.rect(rect.shrink(1.5), 1.0, pal.sniper_fill, Stroke::new(1.0, pal.sniper_stroke), egui::StrokeKind::Inside);
            }
            (Kind::Mine, v) => {
                p.rect(rect.shrink(1.5), 1.0, pal.mine_fill, Stroke::new(1.0, pal.mine_stroke), egui::StrokeKind::Inside);
                if v == 2 {
                    draw_minefield_marker(p, c, v, pal);
                }
            }
            (Kind::Transit, 0) => {
                p.rect(rect.shrink(2.0), 1.0, pal.transit_fill, Stroke::new(1.0, pal.transit_stroke), egui::StrokeKind::Inside);
            }
            (Kind::Transit, 1) => {
                let h = 5.5;
                let pts = vec![
                    c + egui::vec2(-h, -h),
                    c + egui::vec2(0.0, -h),
                    c + egui::vec2(h, 0.0),
                    c + egui::vec2(0.0, h),
                    c + egui::vec2(-h, h),
                    c + egui::vec2(-h * 0.3, 0.0),
                ];
                p.add(egui::Shape::convex_polygon(pts, pal.transit_fill, Stroke::new(1.0, pal.transit_stroke)));
            }
            (Kind::Transit, _) => {
                disc(p, c, size, pal.transit_fill, pal.transit_stroke);
                icon_chevrons(p, c, size, pal.transit_stroke);
            }
            (Kind::Switch, 0) => {
                p.circle(c, 4.5, pal.switch_fill, Stroke::new(1.0, pal.switch_stroke));
            }
            (Kind::Switch, 1) => diamond(p, c, 6.0, pal.switch_fill, Stroke::new(1.0, pal.switch_stroke)),
            (Kind::Switch, _) => {
                disc(p, c, size, pal.switch_fill, pal.switch_stroke);
                icon_bolt(p, c, size, pal.switch_stroke);
            }
            (Kind::Btr, 0) => octagon(p, c, 6.0, pal.btr_fill, Stroke::new(1.0, pal.btr_stroke)),
            (Kind::Btr, 1) => {
                octagon(p, c, 6.0, pal.btr_fill, Stroke::new(1.0, pal.btr_stroke));
                p.rect_filled(Rect::from_center_size(c, egui::vec2(6.0, 1.8)), 0.5, Color32::WHITE);
            }
            (Kind::Btr, _) => {
                disc(p, c, size, pal.btr_fill, pal.btr_stroke);
                octagon(p, c, 3.8, pal.btr_stroke, Stroke::NONE);
            }
        }
        ui.label(label);
    });
}
